/* Throwaway mobile sales design prototype. All records and drafts are illustrative and in memory. */
const app = document.querySelector('#app');
const sheet = document.querySelector('#sheet');
const products = [
 {id:1,name:'قهوة عربية مختصة',category:'القهوة والمشروبات',unit:'كيس 250 جم',price:4200,stock:38,code:'628100100001'},
 {id:2,name:'تمر سكري فاخر',category:'التمور والضيافة',unit:'علبة 1 كجم',price:3500,stock:24,code:'628100100002'},
 {id:3,name:'أكواب ورقية',category:'مستلزمات الضيافة',unit:'عبوة 50 حبة',price:1800,stock:65,code:'628100100003'},
 {id:4,name:'شاي أحمر سيلاني',category:'القهوة والمشروبات',unit:'علبة 100 كيس',price:2400,stock:42,code:'628100100004'},
 {id:5,name:'هيل أخضر فاخر',category:'القهوة والمشروبات',unit:'عبوة 100 جم',price:2800,stock:16,code:'628100100005'},
 {id:6,name:'حقيبة ضيافة',category:'مستلزمات الضيافة',unit:'حبة',price:6500,stock:12,code:'628100100006'},
];
const extraPages={};
const demoShop={name:'محل النخبة',phone:'011 234 5678',address:'الرياض · حي الملقا',fullName:'عبدالله محمد',username:'abdullah'};
const customers=[{id:1,name:'أحمد العتيبي',phone:'050 123 4567'},{id:2,name:'مؤسسة نواة',phone:'055 234 5678'},{id:3,name:'سارة القحطاني',phone:'053 345 6789'}];
const documents=[
 {id:1048,party:'أحمد العتيبي',date:'اليوم، ١٠:٤٢ ص',total:24500,due:0,items:[{id:1,qty:5,price:4200,unit:'كيس 250 جم'},{id:2,qty:1,price:3500,unit:'علبة 1 كجم'}]},
 {id:1047,party:'مؤسسة نواة',date:'اليوم، ٩:٣٠ ص',total:68000,due:18000,items:[{id:2,qty:10,price:3500,unit:'علبة 1 كجم'},{id:6,qty:4,price:6500,unit:'حبة'},{id:5,qty:2.5,price:2800,unit:'عبوة 100 جم'}]},
 {id:1046,party:'بيع نقدي',date:'اليوم، ٩:١٥ ص',total:8400,due:0,items:[{id:1,qty:2,price:4200,unit:'كيس 250 جم'}]},
 {id:1045,party:'سارة القحطاني',date:'أمس، ٦:٢٠ م',total:17500,due:17500,items:[{id:2,qty:5,price:3500,unit:'علبة 1 كجم'}]},
 {id:1044,party:'بيع نقدي',date:'أمس، ٤:١٠ م',total:9600,due:0,items:[{id:4,qty:4,price:2400,unit:'علبة 100 كيس'}]},
];
let state={kind:'sale',view:'sales',tab:'sales',filter:'all',query:'',productQuery:'',category:'all',lines:[],customer:null,discount:0,payment:'cash',paid:0,account:'الصندوق الرئيسي',date:'2026-10-17',draft:null,doc:null,success:false};
const icon=(name)=>`<i data-lucide="${name}" aria-hidden="true"></i>`;
const esc=(s)=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(n)=>new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n/100);
const amount=(n)=>`<span class="num">${money(n)}<span class="currency">ر.س</span></span>`;
const subtotal=()=>state.lines.reduce((n,l)=>n+Math.round(l.qty*l.price),0);
const total=()=>Math.max(0,subtotal()-state.discount+(state.shipping||0));
const paid=()=>state.payment==='cash'?total():state.payment==='credit'?0:state.paid;
function icons(){if(window.lucide)lucide.createIcons({attrs:{'stroke-width':1.7}})}
function toast(s){let el=document.querySelector('#toast');el.textContent=s;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2600)}
function header(title,{back=false,action='',sub=''}={}){return `<header class="topbar">${back?`<button class="icon-btn" data-action="back" aria-label="رجوع">${icon('arrow-right')}</button>`:''}<div class="title-stack"><h2>${title}</h2>${sub?`<div class="topbar-sub">${sub}</div>`:''}</div>${action||`<button class="avatar" data-action="profile" aria-label="حساب عبدالله">ع</button>`}</header>`}
function nav(){return `<nav class="bottom-nav" aria-label="التنقل الرئيسي">${[['home','house','الرئيسية'],['sales','receipt-text','المبيعات'],['products','package','المنتجات'],['finance','wallet','المالية'],['more','grid-2x2','المزيد']].map(([key,i,t])=>`<button data-action="nav" data-view="${key}" class="nav-item ${state.tab===key?'active':''}" ${state.tab===key?'aria-current="page"':''}><span class="nav-icon">${icon(i)}</span>${t}</button>`).join('')}</nav>`}
function stepper(payment=false){return `<div class="stepper"><button class="step ${!payment?'active':''}" data-action="items"><span>${payment?'✓':'١'}</span> المنتجات</button><div class="connector"></div><div class="step ${payment?'active':''}"><span>٢</span> المراجعة والدفع</div></div>`}
function render(){
 const oldScroll=app.querySelector('.app-scroll')?.scrollTop||0;
 const pages={sales:salesPage,home:homePage,editor:editorPage,picker:pickerPage,payment:paymentPage,document:documentPage,products:productsPage,finance:financePage,more:morePage,parties:partiesPage,...extraPages};
 app.innerHTML=(pages[state.view]||salesPage)().replaceAll('محل النخبة',esc(demoShop.name));icons();
 document.querySelectorAll('.journey-step').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view||(b.dataset.view==='editor'&&state.view==='picker')||(b.dataset.view==='payment'&&state.view==='document')));
 if(render.keepScroll){app.querySelector('.app-scroll')?.scrollTo(0,oldScroll);render.keepScroll=false}
}
function salesRows(){
 let docs=documents.filter(d=>(state.filter==='all'||state.filter==='due'&&d.due>0||state.filter==='paid'&&d.due===0)&&(d.party.includes(state.query)||String(d.id).includes(state.query)));
 let html='';let group='';
 docs.forEach(d=>{let g=d.date.startsWith('اليوم')?'اليوم · ١٧ أكتوبر':'أمس · ١٦ أكتوبر';if(group!==g){group=g;html+=`<div class="list-label">${g}</div>`}html+=invoiceRow(d)});
 return html||`<div class="empty">${icon('search')}<h3>لا توجد فواتير مطابقة</h3><p>جرّب اسمًا آخر أو غيّر التصفية.</p></div>`;
}
function invoiceRow(d){return `<button class="invoice-row" data-action="document" data-id="${d.id}"><div class="row between"><span class="invoice-number">INV-${d.id}</span><span class="status ${d.due?'due':''}">${icon(d.due?'clock-3':'check-check')}${d.due?'غير مكتملة الدفع':'مدفوعة'}</span></div><div class="party">${esc(d.party)}</div><div class="row between"><span class="amount">${amount(d.total)}</span><span class="tiny muted">${esc(d.date.split('، ')[1]||'الآن')}${icon('chevron-left')}</span></div>${d.due?`<div class="tiny" style="color:var(--warning);margin-top:5px">المتبقي ${amount(d.due)}</div>`:''}</button>`}
function salesPage(){return header('المبيعات',{sub:'محل النخبة · الفرع الرئيسي'})+`<main class="app-scroll"><section class="sales-summary"><div class="row between"><div><div class="small">مبيعات اليوم</div><div class="summary-number">${amount(documents.filter(d=>d.date.startsWith('اليوم')).reduce((n,d)=>n+d.total,0))}</div></div><span class="summary-emblem">${icon('receipt-text')}</span></div><div class="summary-bottom"><span>${documents.filter(d=>d.date.startsWith('اليوم')).length} فواتير اليوم</span><span>السبت، ١٧ أكتوبر</span></div></section><button class="primary full" data-action="new">${icon('plus')} فاتورة بيع جديدة</button>${state.draft?`<button class="customer-select" data-action="resume" style="margin:13px 0 0"><span class="customer-icon">${icon('file-pen-line')}</span><span>متابعة المسودة<small>${state.draft.lines.length} منتجات · محفوظة في هذه التجربة</small></span>${icon('chevron-left')}</button>`:''}<div class="search">${icon('search')}<input id="invoice-search" placeholder="ابحث برقم الفاتورة أو اسم العميل" aria-label="البحث في الفواتير" value="${esc(state.query)}"></div><div class="chips" role="group" aria-label="تصفية الفواتير">${[['all','الكل'],['paid','المدفوعة'],['due','المتبقي عليها']].map(([f,t])=>`<button class="chip ${state.filter===f?'active':''}" data-action="filter" data-filter="${f}" aria-pressed="${state.filter===f}">${t}</button>`).join('')}</div><div id="sales-results">${salesRows()}</div><p class="list-note">كل المبالغ بالريال السعودي</p></main>`+nav()}
function customerButton(){let c=customers.find(c=>c.id===state.customer);return `<button class="customer-select" data-action="customer"><span class="customer-icon">${icon(c?'user-round-check':'user-round')}</span><span>${c?esc(c.name):'بيع نقدي · بدون عميل'}<small>${c?'اضغط لتغيير العميل':'اختر عميلًا للبيع الآجل أو الدفع الجزئي'}</small></span>${icon('chevron-left')}</button>`}
function editorPage(){return header('فاتورة بيع جديدة',{back:true,action:`<button class="text-button" data-action="save">حفظ مسودة</button>`})+stepper()+`<main class="app-scroll">${customerButton()}<div class="section-heading"><h3>المنتجات <span class="pill-counter">${state.lines.length}</span></h3><label><span class="tiny muted">التاريخ </span><input class="date-input" type="date" aria-label="تاريخ الفاتورة" value="${state.date}" id="invoice-date"></label></div>${state.lines.length?state.lines.map(lineItem).join(''):`<div class="empty">${icon('shopping-bag')}<h3>بماذا نبدأ الفاتورة؟</h3><p>أضف أول منتج، وستظهر تفاصيله هنا.</p></div>`}<button class="dashed" data-action="picker">${icon('plus')} إضافة منتج</button><div class="helper">${icon('info')}<span>اضغط اسم المنتج لتعديل الوحدة والكمية والسعر.</span></div></main><footer class="action-bar"><div class="total-row"><span class="small muted">إجمالي المنتجات</span><span class="grand-total">${amount(subtotal())}</span></div><button class="primary" data-action="review" ${!state.lines.length?'disabled':''}><span>مراجعة الفاتورة والدفع</span>${icon('arrow-left')}</button></footer>`}
function lineItem(l){const p=products.find(p=>p.id===l.id);return `<article class="line-item"><div class="row"><span class="item-visual">${icon('package')}</span><div style="flex:1;min-width:0"><button class="edit-item" data-action="edit" data-id="${l.id}"><span class="item-name">${p.name}</span>${icon('pencil')}</button><div class="item-meta">${esc(l.unit)} · ${money(l.price)} ر.س</div></div><button class="icon-btn" data-action="edit" data-id="${l.id}" aria-label="تعديل ${p.name}">${icon('ellipsis')}</button></div><div class="item-bottom"><div class="quantity-control"><button data-action="qty" data-id="${l.id}" data-delta="-1" aria-label="تقليل كمية ${p.name}">${icon('minus')}</button><span>${l.qty}</span><button data-action="qty" data-id="${l.id}" data-delta="1" aria-label="زيادة كمية ${p.name}">${icon('plus')}</button></div><span class="item-total">${amount(Math.round(l.qty*l.price))}</span></div></article>`}
function filteredProducts(){return products.filter(p=>(state.view!=='picker'||p.active!==false)&&(state.view!=='picker'||state.kind==='sale'||!p.service)&&(state.category==='all'||p.category===state.category)&&(p.name.includes(state.productQuery)||p.code.includes(state.productQuery)))}
function productRows(select=true){let list=filteredProducts();return list.map(p=>{let count=state.lines.find(l=>l.id===p.id)?.qty||0;return `<div class="product-row"><span class="item-visual">${icon('package')}</span><div class="product-info"><div class="item-name">${p.name}</div><small>${p.unit} · متوفر ${p.stock}</small><div>${amount(p.price)}</div></div>${select?`<button class="add-btn ${count?'added':''}" data-action="add" data-id="${p.id}" aria-label="إضافة ${p.name}">${count?count:icon('plus')}</button>`:`<span class="badge-outline">متوفر</span>`}</div>`}).join('')||`<div class="empty">${icon('search')}<h3>لا توجد منتجات مطابقة</h3><p>ابحث بالاسم أو الباركود.</p></div>`}
function pickerPage(){return header('إضافة المنتجات',{back:true,action:`<span class="badge-outline">${state.lines.length} منتجات</span>`})+`<main class="app-scroll"><div class="search" style="margin-top:0">${icon('search')}<input id="product-search" placeholder="اسم المنتج أو الباركود" aria-label="ابحث عن منتج" value="${esc(state.productQuery)}"></div><div class="row between small" style="margin:18px 0 4px"><h3 style="font-size:13px">منتجات المحل</h3><span class="muted">${products.length} منتجات</span></div><div id="product-results">${productRows()}</div></main><footer class="action-bar"><div class="total-row"><span class="small muted">${state.lines.length} منتجات في الفاتورة</span><b>${amount(subtotal())}</b></div><button class="primary" data-action="done-products"><span>العودة إلى الفاتورة</span>${icon('arrow-left')}</button></footer>`}
function paymentPage(){return header('المراجعة والدفع',{back:true,action:`<button class="text-button" data-action="save">حفظ مسودة</button>`})+stepper(true)+`<main class="app-scroll">${customerButton()}<section class="panel"><div class="section-heading"><h3>ملخص الفاتورة</h3><button class="text-button" data-action="items">تعديل المنتجات</button></div><div class="summary-line"><span class="muted">مجموع المنتجات (${state.lines.length})</span>${amount(subtotal())}</div><div class="summary-line"><label for="discount">خصم الفاتورة</label><div class="amount-input"><input id="discount" type="number" min="0" max="${subtotal()/100}" step="0.01" inputmode="decimal" value="${state.discount/100}"><span>ر.س</span></div></div><div class="summary-line total"><span>الإجمالي</span><span id="payment-total">${amount(total())}</span></div></section><section class="panel"><h3 style="font-size:14px">طريقة الدفع</h3><div class="payment-modes">${[['cash','banknote','نقدي'],['credit','calendar-clock','آجل'],['partial','wallet','دفع جزئي']].map(([key,i,t])=>`<button class="payment-mode ${state.payment===key?'active':''}" data-action="payment-mode" data-mode="${key}" aria-pressed="${state.payment===key}" ${!state.customer&&key!=='cash'?'disabled':''}>${icon(i)}${t}</button>`).join('')}</div>${!state.customer?'<p class="disabled-note">اختر عميلًا لتفعيل الآجل أو الدفع الجزئي.</p>':''}${state.payment!=='credit'?`<label class="field">حساب الدفع<select id="account"><option ${state.account==='الصندوق الرئيسي'?'selected':''}>الصندوق الرئيسي</option><option ${state.account==='حساب الراجحي'?'selected':''}>حساب الراجحي</option></select></label>`:''}${state.payment==='partial'?`<label class="field">المبلغ المدفوع (ر.س)<input id="paid" type="number" min="0" max="${total()/100}" step="0.01" inputmode="decimal" value="${state.paid/100}"></label>`:''}<div class="paid-box" id="balances">${balances()}</div></section><div id="payment-error" role="alert"></div><div class="helper">${icon('shield-check')}<span>راجع البيانات قبل الاعتماد. الفاتورة المعتمدة لا تُعدّل مباشرة.</span></div></main><footer class="action-bar"><div class="total-row"><span class="small muted">الإجمالي النهائي</span><span id="footer-total" class="grand-total">${amount(total())}</span></div><button class="primary" data-action="confirm"><span>اعتماد فاتورة البيع</span>${icon('check')}</button></footer>`}
function balances(){return `<div class="summary-line"><span>المدفوع</span>${amount(paid())}</div><div class="summary-line balance"><span>${isBuying()?'المتبقي للمورد':'المتبقي على العميل'}</span>${amount(total()-paid())}</div>`}
function documentPage(){const d=state.doc;return header(state.success?'تم اعتماد الفاتورة':'تفاصيل الفاتورة',{back:true,action:`<span class="status ${d.due?'due':''}">${d.due?'متبقي عليها':'مدفوعة'}</span>`})+`<main class="app-scroll">${state.success?`<div class="success-heading"><div class="success-badge">${icon('check')}</div><h2>تمّت، بكل بساطة.</h2><p>فاتورتك جاهزة · هذه عملية توضيحية فقط</p></div>`:''}<article class="receipt"><div class="receipt-title"><h3>محل النخبة</h3><p>فاتورة بيع · <span dir="ltr">INV-${d.id}</span></p></div><div class="summary-line"><span class="muted">العميل</span><span>${esc(d.party)}</span></div><div class="summary-line"><span class="muted">التاريخ</span><span>${esc(d.date)}</span></div><div style="border-top:1px solid var(--line);margin-top:16px;padding-top:3px">${d.items.map(l=>{let p=products.find(p=>p.id===l.id);return `<div class="receipt-line"><span>${p.name}<small>${l.qty} × ${money(l.price)} ر.س · ${esc(l.unit)}</small></span>${amount(Math.round(l.qty*l.price))}</div>`}).join('')}</div><div class="receipt-footer">${d.discount?`<div class="summary-line"><span class="muted">خصم الفاتورة</span>${amount(d.discount)}</div>`:''}<div class="summary-line total"><span>الإجمالي</span>${amount(d.total)}</div><div class="summary-line"><span class="muted">المدفوع</span>${amount(d.total-d.due)}</div><div class="summary-line"><span class="muted">المتبقي</span>${amount(d.due)}</div></div></article><div class="helper">${icon('info')}<span>البيانات للعرض فقط. لا تُرسل هذه التجربة أي فاتورة ولا تغيّر حسابات المحل.</span></div></main><footer class="action-bar"><button class="primary full" data-action="print">${icon('printer')} طباعة الفاتورة</button>${state.success?'<button class="text-button full" data-action="new">إنشاء فاتورة أخرى</button>':''}</footer>`}
function homePage(){return header('دبت للحسابات',{sub:'محل النخبة'})+`<main class="app-scroll"><div class="home-greeting"><span class="small muted">السبت، ١٧ أكتوبر</span><h2>أهلًا، عبدالله.</h2><p class="small muted">نظرة سريعة على يومك في المحل.</p></div><section class="sales-summary"><div class="small">مبيعات اليوم</div><div class="summary-number">${amount(documents.filter(d=>d.date.startsWith('اليوم')).reduce((n,d)=>n+d.total,0))}</div><div class="summary-bottom"><span>${documents.filter(d=>d.date.startsWith('اليوم')).length} فواتير</span><span>محل النخبة</span></div></section><div class="section-heading"><h3>ابدأ من هنا</h3></div><div class="quick-actions">${[['new','receipt-text','فاتورة بيع'],['nav','package','المنتجات','products'],['nav','users-round','العملاء','parties'],['nav','wallet','المالية','finance']].map(([a,i,t,v])=>`<button class="quick-action" data-action="${a}" data-view="${v||''}">${icon(i)}${t}</button>`).join('')}</div><div class="section-heading"><h3>آخر الفواتير</h3><button class="text-button" data-action="nav" data-view="sales">عرض الكل</button></div>${documents.slice(0,3).map(invoiceRow).join('')}</main>`+nav()}
function productsPage(){return header('المنتجات',{sub:'الأسعار والكميات المتوفرة'})+`<main class="app-scroll"><div class="search" style="margin-top:0">${icon('search')}<input id="product-search" aria-label="ابحث عن منتج" placeholder="اسم المنتج أو الباركود" value="${esc(state.productQuery)}"></div><div class="section-heading"><h3>منتجات المحل</h3><span class="small muted">${products.length} منتجات</span></div><div id="product-results">${productRows(false)}</div><p class="list-note">أسعار وكميات توضيحية</p></main>`+nav()}
function financePage(){return header('المالية',{sub:'الأرصدة وحركة الحسابات'})+`<main class="app-scroll"><div class="section-heading"><h3>حسابات المحل</h3><span class="badge-outline">أرصدة توضيحية</span></div><div class="finance-card"><div class="row between"><h3>الصندوق الرئيسي</h3>${icon('banknote')}</div><div class="num">${amount(1245000)}</div><span class="tiny muted">نقد متوفر</span></div><div class="finance-card"><div class="row between"><h3>حساب الراجحي</h3>${icon('landmark')}</div><div class="num">${amount(2860000)}</div><span class="tiny muted">رصيد الحساب البنكي</span></div><div class="section-heading" style="margin-top:23px"><h3>فواتير لم يكتمل سدادها</h3></div>${documents.filter(d=>d.due>0).map(invoiceRow).join('')}</main>`+nav()}
function partiesPage(){return header('العملاء والموردون',{back:true})+`<main class="app-scroll"><p class="small muted" style="margin-bottom:15px">عملاء المحل</p>${customers.map(c=>`<button class="customer-select" data-action="party-invoices" data-id="${c.id}"><span class="customer-icon">${icon('user-round')}</span><span>${c.name}<small dir="ltr">${c.phone}</small></span>${icon('chevron-left')}</button>`).join('')}</main>`+nav()}
function morePage(){return header('المزيد',{sub:'كل ما تحتاجه لإدارة محلك'})+`<main class="app-scroll"><div class="customer-select"><span class="avatar">ع</span><span>عبدالله محمد<small>مالك المحل · محل النخبة</small></span></div>${[['parties','users-round','العملاء والموردون'],['purchases','shopping-bag','المشتريات'],['stock','boxes','المخزون والاستلام'],['reports','chart-no-axes-combined','التقارير'],['settings','settings-2','الإعدادات والنسخ الاحتياطي']].map(([v,i,t])=>`<button class="more-row" data-action="more-link" data-view="${v}">${icon(i)}${t}${icon('chevron-left')}</button>`).join('')}<div class="welcome-note" style="margin-top:25px"><b>نسخة لاستكشاف التصميم</b>رحلة المبيعات تفاعلية بالكامل. بقية الأقسام توضح التنقل وشكل الواجهة، وتُستكمل بعد اعتماد الاتجاه.</div><button class="secondary full" data-action="reset">${icon('rotate-ccw')} إعادة التجربة من البداية</button></main>`+nav()}
function navigate(view){state.view=view;state.query='';state.productQuery='';if(['home','sales','products','finance','more'].includes(view))state.tab=view;render()}
function newInvoice(){state.kind='sale';state.shipping=0;state.receiptId=null;state.lines=[];state.customer=null;state.discount=0;state.payment='cash';state.paid=0;state.account='الصندوق الرئيسي';state.success=false;state.date='2026-10-17';navigate('editor')}
function saveDraft(){state.draft=structuredClone({kind:state.kind,shipping:state.shipping||0,receiptId:state.receiptId,lines:state.lines,customer:state.customer,discount:state.discount,payment:state.payment,paid:state.paid,account:state.account,date:state.date});if(typeof demo!=='undefined')demo.drafts[state.kind||'sale']=structuredClone(state.draft);toast('حُفظت المسودة في هذه التجربة')}
function seed(){if(!state.lines.length){state.lines=[{id:1,qty:2,price:4200,unit:products[0].unit},{id:2,qty:1,price:3500,unit:products[1].unit},{id:3,qty:2,price:1800,unit:products[2].unit}];state.customer=1}}
function positionSheet(){const r=app.getBoundingClientRect();sheet.style.setProperty('--sheet-left',`${r.left+r.width/2}px`);sheet.style.setProperty('--sheet-top',`${Math.min(innerHeight-250,Math.max(260,r.top+r.height/2))}px`)}
function showSheet(html){sheet.innerHTML=html;positionSheet();sheet.showModal();icons()}
window.addEventListener('resize',positionSheet);
function sheetHead(t){return `<div class="sheet-heading"><h3 id="sheet-title">${t}</h3><button class="icon-btn" data-action="close-sheet" aria-label="إغلاق">${icon('x')}</button></div>`}
function editLine(id){let l=state.lines.find(l=>l.id===id),p=products.find(p=>p.id===id);showSheet(sheetHead('تعديل المنتج')+`<p style="font-size:16px;margin-bottom:4px">${p.name}</p><p class="sheet-help">${p.category}</p><form id="edit-form" data-id="${id}"><label class="field">الوحدة<select name="unit"><option>${esc(l.unit)}</option></select></label><div class="row"><label class="field">الكمية<input name="qty" type="number" min="0.001" max="99999" step="0.001" inputmode="decimal" value="${l.qty}" required></label><label class="field">سعر الوحدة (ر.س)<input name="price" type="number" min="0" max="999999" step="0.01" inputmode="decimal" value="${l.price/100}" required></label></div><div class="summary-line total"><span>إجمالي المنتج</span><span id="edit-total">${amount(Math.round(l.qty*l.price))}</span></div><div class="button-row"><button class="primary" type="submit">حفظ التعديل</button><button class="danger-btn" type="button" data-action="remove" data-id="${id}">${icon('trash-2')} إزالة</button></div></form>`)}
function chooseCustomer(){showSheet(sheetHead('اختيار العميل')+`<p class="sheet-help">يمكن البيع نقدًا بدون عميل. أضف عميلًا لتفعيل الآجل والدفع الجزئي.</p><button class="customer-option" data-action="choose-customer" data-id="0"><span class="avatar">${icon('banknote')}</span><span>بيع نقدي<small>بدون عميل</small></span></button>${customers.map(c=>`<button class="customer-option" data-action="choose-customer" data-id="${c.id}"><span class="avatar">${c.name[0]}</span><span>${c.name}<small dir="ltr">${c.phone}</small></span></button>`).join('')}`)}
function confirmInvoice(){
 if(!state.lines.length||state.discount>subtotal()||state.discount<0||state.payment==='partial'&&(state.paid<=0||state.paid>total())){document.querySelector('#payment-error').innerHTML='<div class="inline-error">تحقق من الخصم والمبلغ المدفوع. يجب ألا يتجاوز المدفوع إجمالي الفاتورة.</div>';document.querySelector('#payment-error').scrollIntoView({block:'nearest'});return}
 showSheet(sheetHead('اعتماد فاتورة البيع؟')+`<p class="sheet-help">سيُحدَّث المخزون والصندوق وحساب العميل في التطبيق الفعلي. هذه التجربة تعرض النتيجة فقط.</p><div class="summary-line total"><span>الإجمالي</span>${amount(total())}</div><div class="summary-line"><span>المدفوع</span>${amount(paid())}</div><div class="summary-line"><span>المتبقي</span>${amount(total()-paid())}</div><div class="button-row"><button class="primary" data-action="post">اعتماد تجريبي</button><button class="secondary" data-action="close-sheet">مراجعة</button></div>`)
}
function back(){if(state.view==='picker')navigate('editor');else if(state.view==='payment')navigate('editor');else if(state.view==='editor'){saveDraft();navigate(state.kind==='sale'?'sales':state.kind==='receiving'?'receiving':'purchases')}else if(state.view==='document'){state.success=false;navigate('sales')}else navigate('more')}
document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(!b)return;let a=b.dataset.action,id=Number(b.dataset.id);if(b.disabled)return;if(typeof handleFeatureAction==='function'&&handleFeatureAction(b))return;
 switch(a){
 case 'nav':navigate(b.dataset.view);break;
 case 'new':if(state.draft){showSheet(sheetHead('لديك مسودة محفوظة')+'<p class="sheet-help">يمكنك متابعة مسودتك، أو بدء فاتورة جديدة مع إبقاء المسودة المحفوظة.</p><div class="button-row"><button class="primary" data-action="resume">متابعة المسودة</button><button class="secondary" data-action="fresh">فاتورة جديدة</button></div>')}else newInvoice();break;
 case 'fresh':sheet.close();newInvoice();break;
 case 'back':back();break;
 case 'save':saveDraft();break;
 case 'resume':Object.assign(state,structuredClone(state.draft));sheet.close();navigate('editor');break;
 case 'preview':if(b.dataset.view!=='sales')seed();navigate(b.dataset.view);break;
 case 'filter':state.filter=b.dataset.filter;render();break;
 case 'document':state.doc=documents.find(d=>d.id===id);state.success=false;navigate('document');break;
 case 'picker':state.productQuery='';navigate('picker');break;
 case 'done-products':navigate('editor');break;
 case 'review':navigate('payment');break;
 case 'items':navigate('editor');break;
 case 'customer':chooseCustomer();break;
 case 'choose-customer':state.customer=id||null;if(!state.customer)state.payment='cash';sheet.close();render();break;
 case 'add':{let l=state.lines.find(l=>l.id===id),p=products.find(p=>p.id===id);if(l)l.qty++;else state.lines.push({id,qty:1,price:state.kind==='sale'?p.price:p.cost,unit:p.unit});render.keepScroll=true;render();break}
 case 'qty':{let l=state.lines.find(l=>l.id===id);if(l.qty+Number(b.dataset.delta)<=0)editLine(id);else{l.qty=Math.round((l.qty+Number(b.dataset.delta))*1000)/1000;render.keepScroll=true;render()}break}
 case 'edit':editLine(id);break;
 case 'remove':state.lines=state.lines.filter(l=>l.id!==id);sheet.close();render();toast('أُزيل المنتج من الفاتورة');break;
 case 'close-sheet':sheet.close();break;
 case 'payment-mode':state.payment=b.dataset.mode;render.keepScroll=true;render();break;
 case 'confirm':confirmInvoice();break;
 case 'post':{const d={id:Math.max(...documents.map(d=>d.id))+1,party:customers.find(c=>c.id===state.customer)?.name||'بيع نقدي',date:`اليوم، ${state.date}`,total:total(),discount:state.discount,due:total()-paid(),items:structuredClone(state.lines)};documents.unshift(d);state.doc=d;state.draft=null;state.success=true;sheet.close();navigate('document');break}
 case 'print':window.print();break;
 case 'profile':showSheet(sheetHead('حسابك')+'<div class="row" style="margin-bottom:15px"><span class="avatar">ع</span><span>عبدالله محمد<br><small class="muted">مالك المحل · محل النخبة</small></span></div><p class="sheet-help">حساب توضيحي لمعاينة التصميم.</p>');break;
 case 'more-link':if(b.dataset.view==='parties')navigate('parties');else showSheet(sheetHead({purchases:'المشتريات',stock:'المخزون والاستلام',reports:'التقارير',settings:'الإعدادات والنسخ الاحتياطي'}[b.dataset.view])+'<p class="sheet-help">هذا القسم خارج نطاق النموذج الأول. رحلة البيع متاحة للتجربة كاملة، ثم يُطبّق الاتجاه المعتمد على بقية الأقسام.</p><button class="primary full" data-action="close-sheet">العودة إلى التجربة</button>');break;
 case 'party-invoices':state.query=customers.find(c=>c.id===id).name;state.view='sales';state.tab='sales';state.filter='all';render();break;
 case 'reset':location.reload();break;
 }
});
document.addEventListener('input',e=>{let t=e.target;if(t.id==='invoice-search'){state.query=t.value;document.querySelector('#sales-results').innerHTML=salesRows();icons()}if(t.id==='product-search'){state.productQuery=t.value;document.querySelector('#product-results').innerHTML=productRows(state.view==='picker');icons()}if(t.id==='discount'||t.id==='paid'){let n=Number(t.value);if(!Number.isFinite(n))return;if(t.id==='discount')state.discount=Math.round(n*100);else state.paid=Math.round(n*100);document.querySelector('#payment-total').innerHTML=amount(total());document.querySelector('#footer-total').innerHTML=amount(total());document.querySelector('#balances').innerHTML=balances();document.querySelector('#payment-error').innerHTML=''}if(t.closest('#edit-form')){const f=t.closest('form');document.querySelector('#edit-total').innerHTML=amount(Math.round(Number(f.elements.qty.value)*Number(f.elements.price.value)*100))}});
document.addEventListener('change',e=>{if(e.target.id==='account')state.account=e.target.value;if(e.target.id==='invoice-date')state.date=e.target.value});
document.addEventListener('submit',e=>{if(e.target.id!=='edit-form')return;e.preventDefault();let f=e.target,l=state.lines.find(l=>l.id===Number(f.dataset.id));l.qty=Number(f.elements.qty.value);l.price=Math.round(Number(f.elements.price.value)*100);l.unit=f.elements.unit.value;const product=products.find(p=>p.id===l.id);l.factor=l.unit===product.unit?1:(product.factor||1);sheet.close();render();toast('تم تحديث المنتج')});
sheet.addEventListener('click',e=>{if(e.target===sheet){const r=sheet.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)sheet.close()}});
render();
